<script setup>
import { computed, onMounted, ref } from 'vue';
import DataTable from 'primevue/datatable';
import Column from 'primevue/column';
import Paginator from 'primevue/paginator';
import Dialog from 'primevue/dialog';
import Image from 'primevue/image';
import RadioButton from 'primevue/radiobutton';
import Textarea from 'primevue/textarea';
import apiClient from '../services/apiClient';
import { useToast } from 'primevue/usetoast';
import { createLogger, logException } from '../utils/logger';

const logger = createLogger('AdminKyc');
const toast = useToast();
const verifications = ref([]); const loading = ref(false); const detailLoading = ref(false); const acting = ref(false); const error = ref(''); const selectedKyc = ref(null); const activeTab = ref('identity'); const rejecting = ref(false); const rejectionReason = ref('');
const meta = ref({ current_page: 1, last_page: 1, total: 0, per_page: 10 });
const rejectionReasons = ['عکس ناخوانا یا تار است', 'عدم تطابق کد ملی با مدرک', 'انقضای مدرک هویتی', 'مدارک یا اطلاعات ناقص است'];
const documentItems = [
    { key: 'national_card_front', label: 'روی کارت ملی', type: 'front' },
    { key: 'national_card_back', label: 'پشت کارت ملی', type: 'back' },
    { key: 'residence', label: 'مدرک سکونت', type: 'residence' },
];
const failedDocuments = ref({});
const documentFallback = 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 88"%3E%3Crect width="120" height="88" rx="12" fill="%23e2e8f0"/%3E%3Crect x="20" y="12" width="80" height="64" rx="10" fill="%23cbd5e1"/%3E%3Ccircle cx="47" cy="36" r="8" fill="%2394a3b8"/%3E%3Cpath d="m31 64 18-18 11 10 9-8 20 16H31Z" fill="%2394a3b8"/%3E%3C/svg%3E';
const visibleRange = computed(() => `${verifications.value.length} پرونده از ${meta.value.total} پرونده`);
const statusLabel = (status) => status === 'approved' ? 'تایید شده' : status === 'rejected' ? 'رد شده' : 'در انتظار بررسی';
const formatDate = (value) => value ? new Intl.DateTimeFormat('fa-IR-u-ca-persian', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '-';
const relativeDate = (value) => { if (!value) return '-'; const date = new Date(value); if (Number.isNaN(date.getTime())) return '-'; const minutes = Math.floor((Date.now() - date.getTime()) / 60000); if (minutes < 60) return minutes < 1 ? 'همین حالا' : `${new Intl.NumberFormat('fa-IR').format(minutes)} دقیقه پیش`; if (minutes < 1440) return `${new Intl.NumberFormat('fa-IR').format(Math.floor(minutes / 60))} ساعت پیش`; return formatDate(value); };

async function load(page = 1) {
    loading.value = true; error.value = '';
    try { const { data } = await apiClient.get('/admin/kyc/pending', { params: { page, per_page: 10 } }); verifications.value = data.data || []; meta.value = data.meta || meta.value; logger.info('load', 'Pending KYC queue loaded', { count: verifications.value.length, total: meta.value.total }); }
    catch (exception) { error.value = 'دریافت صف احراز هویت انجام نشد.'; logger.error('load', 'Pending KYC failed', logException(exception)); }
    finally { loading.value = false; }
}
async function openKyc(row) {
    selectedKyc.value = row; activeTab.value = 'identity'; rejecting.value = false; failedDocuments.value = {}; detailLoading.value = true;
    try { const { data } = await apiClient.get(`/admin/kyc/${row.id}`); selectedKyc.value = data.data; }
    catch (exception) { error.value = 'جزئیات پرونده در دسترس نیست.'; logger.error('openKyc', 'KYC details failed', logException(exception)); }
    finally { detailLoading.value = false; }
}
function closeDialog() { selectedKyc.value = null; rejecting.value = false; rejectionReason.value = ''; }
function removeFromQueue(id) { verifications.value = verifications.value.filter((item) => item.id !== id); meta.value.total = Math.max(0, meta.value.total - 1); }
async function approve() {
    if (!selectedKyc.value) return; acting.value = true;
    try { await apiClient.patch(`/admin/kyc/${selectedKyc.value.id}/approve`); removeFromQueue(selectedKyc.value.id); closeDialog(); toast.add({ severity: 'success', summary: 'احراز هویت تایید شد', detail: 'پرونده با موفقیت تایید و دسترسی کاربر فعال شد.', life: 3500 }); }
    catch (exception) { error.value = 'تایید پرونده انجام نشد.'; logger.error('approve', 'KYC approval failed', logException(exception)); toast.add({ severity: 'error', summary: 'خطا در تایید', detail: 'وضعیت پرونده تغییر کرده است. صف را به‌روزرسانی کنید.', life: 4000 }); }
    finally { acting.value = false; }
}
async function reject() {
    if (!selectedKyc.value || !rejectionReason.value) return; acting.value = true;
    try { await apiClient.post(`/api/admin/kyc/${selectedKyc.value.id}/reject`, { rejection_reason: rejectionReason.value }); removeFromQueue(selectedKyc.value.id); closeDialog(); toast.add({ severity: 'success', summary: 'پرونده رد شد', detail: 'علت رد برای ارسال مجدد به کاربر ثبت شد.', life: 3500 }); }
    catch (exception) { error.value = 'رد پرونده انجام نشد.'; logger.error('reject', 'KYC rejection failed', logException(exception)); toast.add({ severity: 'error', summary: 'خطا در رد پرونده', detail: 'وضعیت پرونده تغییر کرده است. صف را به‌روزرسانی کنید.', life: 4000 }); }
    finally { acting.value = false; }
}
async function copyNationalCode(code) { if (!code) return; try { await navigator.clipboard.writeText(code); toast.add({ severity: 'success', summary: 'کپی شد', detail: 'کد ملی در کلیپ‌بورد قرار گرفت.', life: 1800 }); } catch { toast.add({ severity: 'warn', summary: 'کپی ناموفق بود', detail: 'کد ملی را به‌صورت دستی انتخاب کنید.', life: 2500 }); } }
function documentUrl(type) {
    const urls = {
        national_card_front: selectedKyc.value?.id_card_front_url,
        national_card_back: selectedKyc.value?.id_card_back_url,
        residence: selectedKyc.value?.residence_doc_url,
    };
    return urls[type] || selectedKyc.value?.documents?.[type] || '';
}
function documentPath(type) { return failedDocuments.value[type] || !documentUrl(type) ? documentFallback : documentUrl(type); }
function handleDocumentError(type) { failedDocuments.value = { ...failedDocuments.value, [type]: true }; }
onMounted(load);
</script>

<template>
    <section class="kyc-page">
        <header class="kyc-page__header"><div><span>عملیات / احراز هویت</span><h1>صف بررسی مدارک هویتی</h1><p>پرونده‌های در انتظار بررسی اپراتور را با دقت ارزیابی کنید.</p></div><button class="refresh-button" type="button" :disabled="loading" @click="load(meta.current_page)"><i :class="loading ? 'pi pi-spin pi-refresh' : 'pi pi-refresh'"></i>به‌روزرسانی</button></header>
        <p v-if="error" class="kyc-error" role="alert"><i class="pi pi-exclamation-triangle"></i>{{ error }}</p>
        <div class="table-card"><DataTable :value="verifications" dataKey="id" :loading="loading" stripedRows responsiveLayout="scroll"><Column field="id" header="شماره پرونده" /><Column header="کاربر"><template #body="slotProps"><div class="user-cell"><span class="avatar">{{ (slotProps.data.user?.name || 'ک').slice(0, 1) }}</span><div><strong>{{ slotProps.data.user?.name || '-' }}</strong><small>{{ slotProps.data.user?.mobile || '-' }}</small></div></div></template></Column><Column header="کد ملی"><template #body="slotProps"><div class="national-code"><span>{{ slotProps.data.national_code || slotProps.data.user?.national_code || '-' }}</span><button type="button" title="کپی کد ملی" @click="copyNationalCode(slotProps.data.national_code || slotProps.data.user?.national_code)"><i class="pi pi-copy"></i></button></div></template></Column><Column header="تاریخ ثبت"><template #body="slotProps"><span class="date-cell" :title="formatDate(slotProps.data.created_at)">{{ relativeDate(slotProps.data.created_at) }}</span></template></Column><Column header="وضعیت"><template #body><span class="status-badge"><i class="pi pi-clock"></i>در انتظار بررسی</span></template></Column><Column header="عملیات"><template #body="slotProps"><button class="review-button" type="button" @click="openKyc(slotProps.data)"><i class="pi pi-eye"></i>مشاهده پرونده</button></template></Column><template #empty><div class="empty-state"><i class="pi pi-inbox"></i><p>در حال حاضر هیچ پرونده احراز هویتی در صف بررسی وجود ندارد.</p></div></template></DataTable><footer class="table-footer"><span>نمایش {{ visibleRange }}</span><Paginator :first="(meta.current_page - 1) * meta.per_page" :rows="meta.per_page" :totalRecords="meta.total" :rowsPerPageOptions="[10]" @page="load($event.page + 1)" /></footer></div>
        <Dialog :visible="Boolean(selectedKyc)" modal :closable="false" :style="{ width: 'min(900px, 94vw)' }" class="kyc-review-dialog" @update:visible="(value) => !value && closeDialog()"><template #header><div v-if="selectedKyc" class="dialog-header"><div><span>بررسی پرونده هویتی</span><h2>{{ selectedKyc.user?.name || 'کاربر' }}</h2></div><div class="dialog-header__meta"><b>#{{ selectedKyc.id }}</b><em><i class="pi pi-clock"></i>{{ statusLabel(selectedKyc.status) }}</em><button type="button" aria-label="بستن" @click="closeDialog"><i class="pi pi-times"></i></button></div></div></template><div v-if="detailLoading" class="dialog-loading"><i class="pi pi-spin pi-spinner"></i>در حال دریافت جزئیات پرونده...</div><div v-else-if="selectedKyc" class="kyc-dialog-body"><nav class="kyc-tabs"><button type="button" :class="{ active: activeTab === 'identity' }" @click="activeTab = 'identity'"><i class="pi pi-user"></i>اطلاعات هویتی</button><button type="button" :class="{ active: activeTab === 'documents' }" @click="activeTab = 'documents'"><i class="pi pi-images"></i>مدارک و تصاویر</button><button type="button" :class="{ active: activeTab === 'history' }" @click="activeTab = 'history'"><i class="pi pi-history"></i>سوابق کاربری</button></nav><section v-if="activeTab === 'identity'" class="tab-panel"><div class="info-grid"><div><small>نام و نام خانوادگی</small><strong>{{ selectedKyc.user?.name || '-' }}</strong></div><div><small>کد ملی</small><strong class="mono-value">{{ selectedKyc.national_code || selectedKyc.user?.national_code || '-' }}</strong><span class="match-ok"><i class="pi pi-check-circle"></i>استعلام اولیه ثبت شد</span></div><div><small>موبایل ثبت‌نامی</small><strong>{{ selectedKyc.user?.mobile || '-' }}</strong><span class="muted-caption">مالکیت سیم‌کارت به نام متقاضی</span></div><div><small>تاریخ تولد</small><strong>{{ formatDate(selectedKyc.user?.birth_date) }}</strong></div><div><small>شهر و استان سکونت</small><strong>{{ selectedKyc.user?.city?.name || '-' }}، {{ selectedKyc.user?.province?.name || '-' }}</strong></div><div><small>آدرس پستی</small><strong>{{ selectedKyc.postal_address || '-' }}</strong></div></div></section><section v-else-if="activeTab === 'documents'" class="tab-panel"><div class="document-grid"><article v-for="document in [{ key: 'national_card_front', label: 'روی کارت ملی', type: 'national-card-front' }, { key: 'national_card_back', label: 'پشت کارت ملی', type: 'national-card-back' }, { key: 'residence', label: 'مدرک سکونت', type: 'residence' }].filter((item) => documentPath(item.key))" :key="document.key" class="document-card"><div class="document-preview"><Image :src="documentPath(document.key)" :alt="document.label" preview /><i v-if="!documentPath(document.key)" class="pi pi-image"></i></div><div><strong>{{ document.label }}</strong><a :href="documentPath(document.key)" target="_blank" download><i class="pi pi-download"></i>دانلود فایل</a></div></article></div><div class="validation-checklist"><strong>چک‌لیست اعتبارسنجی اپراتور</strong><label><input type="checkbox" /> عکس واضح است؟</label><label><input type="checkbox" /> کد ملی با کارت همخوان است؟</label><label><input type="checkbox" /> تاریخ انقضای کارت معتبر است؟</label></div></section><section v-else class="tab-panel"><div class="account-grid"><div><small>تاریخ عضویت در سامانه</small><strong>{{ formatDate(selectedKyc.user?.created_at) }}</strong></div><div><small>تعداد آگهی‌های ثبت‌شده</small><strong>{{ selectedKyc.user?.advertisements_count ?? 0 }} آگهی</strong></div><div><small>شماره شبای بانکی</small><strong class="mono-value">{{ selectedKyc.iban || selectedKyc.user?.iban || '-' }}</strong></div><div><small>تطابق نام با حساب</small><strong class="match-ok"><i class="pi pi-check-circle"></i>تایید مالکیت توسط متقاضی</strong></div></div></section></div><footer v-if="selectedKyc && !detailLoading" class="decision-footer"><button class="close-button" type="button" @click="closeDialog">بستن</button><div v-if="rejecting" class="reject-form"><div v-for="reason in rejectionReasons" :key="reason"><RadioButton v-model="rejectionReason" name="kyc-reason" :inputId="reason" :value="reason" /><label :for="reason">{{ reason }}</label></div><button class="reject-submit" type="button" :disabled="acting || !rejectionReason" @click="reject">ثبت رد مدارک</button></div><div v-else class="decision-actions"><button class="reject-button" type="button" @click="rejecting = true"><i class="pi pi-times"></i>رد مدارک</button><button class="approve-button" type="button" :disabled="acting" @click="approve"><i :class="acting ? 'pi pi-spin pi-spinner' : 'pi pi-check'"></i>{{ acting ? 'در حال ثبت...' : 'تایید نهایی احراز هویت' }}</button></div></footer></Dialog>
    </section>
</template>

