n-left: 4px; }.muted-caption { display: block; margin-top: 4px; color: #94a3b8; font-size: 9px; }.document-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }.document-card { overflow: hidden; border: 1px solid #e2e8f0; border-radius: 10px; background: #fff; }.document-preview { display: grid; height: 130px; place-items: center; background: #f8fafc; }.document-preview :deep(img) { width: 100%; height: 100%; object-fit: contain; }.document-card > div:last-child { display: flex; align-items: center; justify-content: space-between; gap: 7px; padding: 9px; }.document-card strong { color: #334155; font-size: 10px; }.document-card a { color: #a62626; font-size: 9px; text-decoration: none; white-space: nowrap; }.document-card a i { margin-left: 4px; }.validation-checklist { display: grid; gap: 9px; margin-top: 16px; padding: 14px; border: 1px solid #e2e8f0; border-radius: 10px; background: #f8fafc; color: #475569; font-size: 10px; }.validation-checklist strong { color: #334155; font-size: 11px; }.validation-checklist label { display: flex; gap: 7px; align-items: center; }.decision-footer { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 14px 24px; border-top: 1px solid #f1f5f9; background: #f8fafc; }.decision-actions, .reject-form { display: flex; align-items: center; gap: 8px; margin-right: auto; }.close-button, .reject-button, .approve-button, .reject-submit { display: inline-flex; align-items: center; gap: 6px; padding: 9px 13px; border: 0; border-radius: 8px; cursor: pointer; font: inherit; font-size: 10px; font-weight: 800; }.close-button { background: #e2e8f0; color: #475569; }.reject-button, .reject-submit { background: #fee2e2; color: #b91c1c; }.approve-button { background: #16a34a; color: #fff; }.approve-button:disabled, .reject-submit:disabled { cursor: wait; opacity: .55; }.reject-form { flex-wrap: wrap; justify-content: flex-end; }.reject-form > div { display: flex; align-items: center; gap: 5px; color: #475569; font-size: 9px; }.reject-form .reject-submit { background: #a62626; color: #fff; }.dialog-loading { padding: 55px; color: #64748b; text-align: center; font-size: 11px; }.dialog-loading i { margin-left: 8px; color: #a62626; }
